import openpyxl

wb = openpyxl.load_workbook(r'C:\Users\Blackmai\.claude\222\出差费用报销单（创新中心版本）-例子.xlsx')
print('=== EXAMPLE SHEETS ===')
print(wb.sheetnames)

for sname in wb.sheetnames:
    ws = wb[sname]
    print(f'\n--- Sheet: {sname} ---')
    print(f'Dimensions: {ws.dimensions}, Rows: {ws.max_row}, Cols: {ws.max_column}')
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 30), values_only=False):
        row_data = []
        for cell in row:
            if cell.value is not None:
                font_info = ''
                if cell.font and cell.font.color:
                    try:
                        if cell.font.color.rgb:
                            font_info = f' [font_color: {cell.font.color.rgb}]'
                    except:
                        pass
                row_data.append(f'{cell.coordinate}: {cell.value}{font_info}')
        if row_data:
            print('  ' + ' | '.join(row_data))
    if ws.max_row > 30:
        print(f'  ... ({ws.max_row - 30} more rows)')

wb.close()
"@
